const why = {
  buttons: `<div class="why"><p>Padoms: pogas piekļūstamajam nosaukumam ir skaidri jānorāda, ko poga darīs, kad uz tās noklikšķinās. Ja tas mainās, ir jābūt skaidram arī pašreizējam stāvoklim:</p><ul><li>Pogas, kurām mainās etiķete:<br>“Atskaņot/Pauzēt”, “Rādīt detaļas/Slēpt detaļas”</li><li>Pogas, kas <a href="https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Reference/Roles/button_role#associated_aria_roles_states_and_properties">maina stāvokli</a>:<br>“Atskaņot/Atskaņot, nospiesta”, “Detaļas, sakļautas/Detaļas, izvērstas”</li></ul></div>`,
  fix: `<strong class="badge">Kā labot</strong> `,
  headings: `<div class="why"><p>Padoms: virsraksti un apakšvirsraksti organizē saturu ligzdotā struktūrā. Ekrānlasītāju lietotāji paļaujas uz šo struktūru, lai saprastu lapas un pārvietotos tajās:</p><ul><li>1. līmeņa virsraksts: lapas nosaukumi<ul><li>2. līmeņa virsraksts: galvenās tēmas<ul><li>3. līmeņa virsraksts: apakštēmas</li></ul></li></ul></li></ul></div>`,
  imageLinks: `<div class="why"><p>Padoms: alternatīvais teksts ir paredzēts, lai aizstātu to, ko attēls nozīmē, nevis to, kas tajā redzams. Attēla ar saiti nozīme ir saites galamērķis:</p><ul><li>“<em>Lupa</em>” apraksta attēlu, nevis saiti.</li><li>“<em>Meklēšanas lupa</em>” mulsinoši apraksta abus.</li><li>“<em>Meklēt</em>” precīzi apraksta saites galamērķi.</li></ul></div>`,
  images: `<div class="why"><p>Padoms: rakstot alternatīvo tekstu, aprakstiet, ko attēls nozīmē, nevis tikai ko tas satur. Atkarībā no konteksta fotoattēls, kurā bērns sper bumbu, var nozīmēt:</p><ul><li>Viņi spēlēja lietusgāzē.</li><li>Jaunajām komandas formām ir forši pūķu logotipi.</li><li>Viņa guva uzvaras vārtus no kreisās malas!</li></ul></div>`,
  links: `<div class="why"><p>Padoms: lasītāji pārskata lapu, vadoties pēc saitēm, un ar meklēšanu lapā atrod saites pēc nosaukuma, tāpēc labām saitēm jābūt jēgpilnām, unikālām un kodolīgām:</p><ul><li>Ideāli: “Uzziniet par <a href="https://webaim.org/techniques/hypertext/link_text">jēgpilnām saitēm</a>”</li><li>Nav unikāla: “Noklikšķiniet <a href="https://webaim.org/techniques/hypertext/link_text">šeit</a>, lai uzzinātu par jēgpilnām saitēm.”</li>
	<li>Nav kodolīga: “<a href="https://webaim.org/techniques/hypertext/link_text">Noklikšķiniet šeit, lai uzzinātu vairāk par jēgpilnām saitēm</a>”</li></ul></div>`
};
const tips = {
  ALT_FILE_EXT: `<p><span hidden>%(alt)</span><strong>Alternatīvais teksts:</strong> <i>%(ALT_TEXT)</i></p><p>Ekrānlasītāji mēģinās izrunāt šo URL, bieži burtu pa burtam. Tas, visticamāk, nesniedz tādu pašu nozīmi kā attēla redzēšana.</p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  ALT_MAYBE_BAD: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  ALT_MAYBE_BAD_WARNING: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  ALT_PLACEHOLDER: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  ALT_UNPRONOUNCEABLE: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>Šis alternatīvais teksts satur tikai neizrunājamus simbolus un/vai atstarpes. Ekrānlasītāji paziņos, ka ir attēls, un pēc tam neveikli apklusīs vai pateiks kaut ko nesaprotamu.</p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  ARIA_INPUT_FIELD_NAME: `<p><strong>Elements:</strong> <code>%(EL)</code></p><p>${why.fix}Norādiet jebkuru derīgu etiķeti; pielāgotiem ievades elementiem tas bieži nozīmē iekšējo tekstu vai title, aria-label vai aria-labelledby atribūtu.</p>`,
  BTN_EMPTY: `<p>${why.fix}Izmantojiet jebkuru derīgu metodi, lai ekrānlasītājiem pastāstītu, ko šī poga dara, piemēram, tekstu, ikonas alternatīvo tekstu vai title atribūtu.</p>`,
  BTN_EMPTY_LABELLEDBY: `<p>Šai pogai ir <code>aria-labelledby</code> vērtība, kas ir tukša vai neatbilst neviena cita elementa <code>ID</code> vērtībai lapā.</p><p>${why.fix}Atkārtoti sasaistiet ID ar lapā esošu elementu vai noņemiet šo atribūtu un aprakstiet pogu citā veidā.</p>`,
  BTN_ROLE_IN_NAME: `<p><strong>Ekrānlasītāja etiķete:</strong> <i>%(TEXT)</i></p><p>Ekrānlasītāji paši pasaka vārdu “poga”, lai paziņotu, ka apraksta pogu, tāpēc šis vārds ir lieks.</p><p>${why.fix}Pogas etiķetei jāatbilst tās darbībai. Ja redzamā etiķete ir ikona, nevis teksts, norādiet pogas etiķetē ikonas nozīmi, piemēram, “Atskaņot”, “Meklēt” vai “Izvēlne”.</p>`,
  BTN_TIP: `${why.buttons}`,
  BTN_UNPRONOUNCEABLE: `<p><strong>Pogas teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Pievienojiet tekstu, title atribūtu vai aria-label, kas apraksta, ko poga dara.</p><div class="why"><p>Padoms: ekrānlasītāji nevar aprakstīt pogas, kas satur tikai atstarpes vai simbolus. Tās vai nu apklust (“Poga, [...neveikla pauze, kur vajadzētu būt pogas nosaukumam...]”), vai nolasa simbola nosaukumu.</p></div>`,
  CONTRAST_WARNING: "Fona attēla vai krāsu pārejas dēļ šis rīks nevar droši noteikt, kāda krāsa ir aiz šī teksta. Pārbaudiet to manuāli ar tālāk esošo krāsu atlasītāju.",
  DUPLICATE_ID: `<p>Šajā lapā ID tiek izmantoti etiķetēm vai saišu mērķiem, kas nozīmē, ka tiem jābūt unikāliem.</p><p>${why.fix}Mainiet šo ID: <code>#%(ID)</code></p><div class="why"><p>Lielākajā daļā satura pārvaldības sistēmu tas tiek iestatīts elementa rekvizītu laukā “name” vai “id”. HTML kodā tas ir atribūts: <code>&lt;a id="MANS-ID"&gt;</code></p></div>`,
  DUPLICATE_TITLE: `<p>${why.fix}Dzēsiet saites tekstu vai tās <code>title</code> atribūtu.</p><div class="why"><p>Padoms: <code>title</code> rīka padomi tiek rādīti tikai tad, kad uz elementa novieto peles rādītāju. Tos nevar redzēt, lietojot tālruni vai tastatūru, tāpēc daudzi lietotāji tos nekad neredzēs. Tajos nekad nedrīkst būt unikāla vai svarīga informācija.</p></div>`,
  EMBED_AUDIO: `<p>Šis rīks nevar noteikt, vai audio atskaņotājam ir atšifrējums un vai tas ir precīzs.</p><p>${why.fix}Pārliecinieties, ka ir pieejams <a href="https://www.w3.org/WAI/media/av/transcribing/">atšifrējums vai teksta alternatīva</a> un ka runātāji un nozīmīgie skaņu efekti ir precīzi identificēti.</p>`,
  EMBED_DATA_VIZ: `<p>Iegultos vizualizāciju logrīkus ar palīgtehnoloģijām bieži ir grūti vai pat neiespējami lietot, lasītājiem ar vāju redzi vai krāsu aklumu tos var būt grūti saprast, un tālruņos tie var prasīt daudz ritināt horizontāli.</p><p>${why.fix}Ja vien šim konkrētajam iegultajam saturam nav augsts vizuālais kontrasts, tas nav vadāms ar tastatūru <strong><em>un</em></strong> aprakstāms ar ekrānlasītāju, pievienojiet līdzvērtīgu alternatīvu formātu, piemēram, teksta aprakstu, datu tabulu vai lejupielādējamu izklājlapu.</p>`,
  EMBED_GENERAL: 'Automātiskie rīki nevar pārbaudīt iegulto elementu saturu. Pārliecinieties, ka kāds ir pārbaudījis, vai visiem šī iegultā elementa attēliem ir alternatīvais teksts, videoklipiem ir subtitri, tekstam ir pietiekams kontrasts un saites un pogas ir <a href="https://webaim.org/techniques/keyboard/">pieejamas ar tastatūru</a>.',
  EMBED_MISSING_TITLE: `<p>Iegultajiem elementiem nepieciešams piekļūstams nosaukums, kas apraksta to saturu ekrānlasītājiem.</p><p>${why.fix}Norādiet unikālu <code>title</code> vai <code>aria-label</code> atribūtu.</p>`,
  EMBED_UNFOCUSABLE: `<p>Šis atribūts liek tastatūras navigācijai un palīgtehnoloģijām izlaist šo elementu. Noņemiet šo atribūtu, ja vien iframe nav saišu, pogu, veidlapu elementu vai ritināma satura.</p>`,
  EMBED_VIDEO: `<p>Šis rīks nevar “redzēt”, vai videoklipiem ir subtitri un vai kāds tos ir pārlasījis, tāpēc nepieciešama manuāla pārbaude.</p><p>${why.fix}Pārliecinieties, ka ir pieejami <a href="https://www.w3.org/WAI/media/av/captions/">precīzi subtitri nedzirdīgajiem (“CC”) vai parastie subtitri</a> un ka runātāji un nozīmīgie skaņu efekti ir precīzi identificēti.</p>`,
  HEADING_EMPTY: `<p>Tukši virsraksti rada mulsinošus robus lapas struktūrā.</p><p>${why.fix}Pievienojiet šim virsrakstam tekstu vai izdzēsiet šo tukšo rindiņu.</p>${why.headings}`,
  HEADING_UNPRONOUNCEABLE: `<p>Tukši virsraksti rada mulsinošus robus lapas struktūrā.</p><p>${why.fix}Pievienojiet šim virsrakstam cilvēkam saprotamu tekstu vai pārveidojiet to par rindkopu.</p>${why.headings}`,
  HEADING_EMPTY_WITH_IMAGE: `<p>Tukši virsraksti rada mulsinošus robus lapas struktūrā.</p><p>${why.fix}Ja tas nav virsraksts, mainiet tā formātu no <code>Virsraksts %(level)</code> uz <code>Rindkopa</code>. Pretējā gadījumā aprakstiet attēla nozīmi tā alternatīvajā tekstā.</p>${why.headings}`,
  HEADING_FIRST: `${why.fix}Pārliecinieties, ka lapas nosaukums ir formatēts kā 1. vai 2. līmeņa virsraksts. ${why.headings}`,
  HEADING_LONG: `<p>${why.fix}Ja vien šis virsraksts nav fiksēta atsauce, piemēram, publicēta raksta nosaukums, saīsiniet to, lai lapu būtu vieglāk ātri pārskatīt:<span hidden>%(drop)%(drop)</span></p><p><i>%(TEXT)</i></p>${why.headings}`,
  HEADING_MISSING_ONE: `<p>${why.fix}Formatējiet lapas nosaukumu kā 1. līmeņa virsrakstu, lai iezīmētu dokumenta struktūras sākumu.</p>${why.headings}`,
  HEADING_SKIPPED_LEVEL: `<p>Šis virsraksts pārlec no <code>%(prevLevel). līmeņa</code> uz <code>%(level). līmeni</code>. Klausoties ar ekrānlasītāju, šķiet, ka daļa satura trūkst.</p><p>${why.fix}Pielāgojiet līmeņus, lai izveidotu precīzu struktūru bez robiem.</p>${why.headings}`,
  HIDDEN_FOCUSABLE: `<p>Šim interaktīvajam elementam ir atribūts <code>aria-hidden=&quot;true&quot;</code>, bet tas joprojām ir fokusējams ar tastatūru.</p><p>${why.fix}Ja <strong>tīši</strong> slēpjat šo elementu no ekrānlasītājiem, jums jāpievieno arī <code>tabindex=&quot;-1&quot;</code>. Pretējā gadījumā noņemiet atribūtu <code>aria-hidden=&quot;true&quot;</code>.</p><p><strong>Elements:</strong> <code>%(ELEMENT)</code></p>`,
  IMAGE_ALT_TOO_LONG: `<p>Alternatīvā teksta garums (rakstzīmēs): %(altLength). <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Saīsiniet to vai pārvietojiet daļu apraksta uz parakstu.</p><div class="why"><p>Padoms: sarežģītiem attēliem, kas sniedz vairāk informācijas nekā ietilpst vienā teikumā, parasti nepieciešams <strong>redzams</strong> paraksts vai alternatīva, kas apraksta vai skaidro galvenās detaļas. Ekrānlasītāju lietotājus drīkst novirzīt uz šādu tekstu:</p><ul><li>“Piektdienas balles plakāts; sīkāka informācija parakstā.”</li><li>“Diagramma: problēmu šogad ir par 10% mazāk; sīkāka informācija tabulā.”</li></ul></div>`,
  IMAGE_DECORATIVE: `<p>Šis attēls ir paslēpts no ekrānlasītājiem, izmantojot tukšu alternatīvo tekstu. Šādi drīkst slēpt tikai attēlus bez nozīmes, piemēram, liekas ikonas un fona faktūras.</p><p>${why.fix}Ja šis attēls papildina lapas saturu, norādiet alternatīvo tekstu.</p>${why.images}`,
  IMAGE_DECORATIVE_CAROUSEL: "Attēls ir atzīmēts kā <strong>dekoratīvs</strong>, bet visiem attēliem karuselī vai galerijā jābūt aprakstošam alternatīvajam tekstam, lai nodrošinātu līdzvērtīgu pieredzi visiem.",
  IMAGE_FIGURE_DECORATIVE: `<p>Palīgtehnoloģijas ignorēs šo attēlu. Vai tā paraksts būs saprotams bez attēla?</p><p>${why.fix}Ja paraksts neapraksta attēla vizuālo nozīmi, norādiet alternatīvo tekstu tam, ko paraksts neapraksta.</p><div class="why"><p>Padoms: attēli, alternatīvie teksti un paraksti darbojas kopā:</p><ul><li>Redzamie paraksti sniedz attēla kontekstu un skaidrojumu.</li><li>Neredzamie alternatīvie teksti apraksta attēlu cilvēkiem, kuri to nevar redzēt, lai viņi zinātu, ko paraksts apraksta.</li></ul></div>`,
  IMAGE_FIGURE_DUPLICATE_ALT: `<p><strong>Dublēts teksts: </strong><i>%(ALT_TEXT)</i></p><p>${why.fix}Aprakstiet alternatīvajā tekstā jebkuru trūkstošo vizuālo nozīmi.</p><div class="why"><p>Padoms: attēli, alternatīvie teksti un paraksti darbojas kopā:</p><ul><li>Redzamie paraksti sniedz attēla kontekstu un skaidrojumu.</li><li>Neredzamie alternatīvie teksti apraksta attēlu cilvēkiem, kuri to nevar redzēt, lai viņi zinātu, par ko ir paraksts.</li></ul></div>`,
  LABEL_IN_NAME: `<p><strong>Redzamais teksts:</strong> <i>%(VISIBLE)</i></p><p><strong>Ekrānlasītāja etiķete:</strong> <i>%(LABEL)</i></p><p>Šī elementa redzamais teksts, šķiet, atšķiras no tā piekļūstamā nosaukuma. Tas var mulsināt ekrānlasītāju lietotājus un traucēt balss vadību.</p><p>${why.fix}Pārliecinieties, ka redzamā etiķete sākas ar neredzamās etiķetes tekstu un nesatur nekādu jēgpilnu informāciju, kuras trūkst neredzamajā etiķetē.</p>`,
  LABELS_ARIA_LABEL_INPUT: `<p><strong>Neredzamā lauka etiķete:</strong> <i>%(TEXT)</i></p><p>Pārbaudiet, vai laukam ir redzama etiķete, vai tā paliek redzama, kad laukā ir teksts, un vai tā atbilst neredzamajam lauka nosaukumam.</p><div class="why"><p>Ja laukam etiķetes vietā ir tikai title atribūts vai vietturis, etiķete pazūd, tiklīdz kāds sāk rakstīt. Ja lauku ir vairāki, tas apgrūtina ievadītā pārskatīšanu. Turklāt ir viegli aizmirst atjaunināt neredzamo lauka etiķeti.</p></div>`,
  LABELS_INPUT_RESET: `<p>Atiestatīšanas pogas ir viegli nejauši aktivizēt, izraisot datu zudumu bez iespējas atcelt vai atsaukt.</p><p>${why.fix}Ja vien tā neatiestata tikai vienu lauku, apsveriet iespēju to noņemt vai ļaut atcelt darbību, pirms tā tiek izpildīta.</p>`,
  LABELS_MISSING_IMAGE_INPUT: "Attēla pogai trūkst alternatīvā teksta. Lūdzu, pievienojiet alternatīvo tekstu, lai nodrošinātu piekļūstamu nosaukumu. Piemēram: <em>Meklēt</em> vai <em>Iesniegt</em>.",
  LABELS_MISSING_LABEL: `<p>${why.fix}Pievienojiet šim ievades laukam <code>id</code> un etiķetei pievienojiet atbilstošu <code>for</code> atribūtu.</p>`,
  LABELS_NO_FOR_ATTRIBUTE: "Ar šo ievades lauku nav saistīta neviena etiķete. Pievienojiet <code>for</code> atribūtu etiķetei, kas atbilst šī ievades lauka <code>id</code>. <hr> <strong>ID:</strong> <code>#%(ID)</code>",
  LABELS_PLACEHOLDER: `<p>Ja viettura tekstam ir labs kontrasts, to var sajaukt ar jau ievadītu saturu, bet, ja kontrasts ir vājš, to ir grūti izlasīt. Turklāt tas pazūd, tiklīdz sāk rakstīt, un lietotāji var zaudēt informāciju, kas vajadzīga, lai pārbaudītu kļūdas.</p><p>${why.fix}Pārliecinieties, ka galvenā informācija, piemēram, lauka etiķete, palīdzības teksts un formāta norādījumi, paliek redzama, kad šajā laukā ir saturs, un apsveriet viettura pilnīgu noņemšanu.</p>`,
  LINK_ALT_FILE_EXT: `<p>Šis alternatīvais teksts, visticamāk, ir faila nosaukums, nevis jēgpilna saites etiķete:<br><span hidden>%(ALT)</span><i>%(alt)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p><div class="why"><p>Alternatīvais teksts ir paredzēts, lai aizstātu to, ko attēls nozīmē, nevis to, kas tajā redzams. Attēla ar saiti nozīme ir saites galamērķis:</p><ul><li>“Lapa ar rokrakstu” apraksta attēlu, nevis saiti.</li><li>“IMG_1234.jpg” ir tikai faila nosaukums.</li><li>“Pasākuma reģistrācijas veidlapa (.doc)” ir saites galamērķis.</li></ul></div>`,
  LINK_ALT_MAYBE_BAD: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_ALT_MAYBE_BAD_WARNING: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_ALT_UNPRONOUNCEABLE: `<p>Šī attēla ar saiti alternatīvais teksts satur tikai neizrunājamus simbolus un/vai atstarpes: <i>%(ALT_TEXT)</i></p><p>Ekrānlasītāji paziņos, ka ir saite, un pēc tam nespēs to aprakstīt.</p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_CLICK_HERE: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Noņemiet liekos vārdus, kas novērš uzmanību no saites mērķa.</p>${why.links}`,
  LINK_DOI: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Par saiti padariet raksta nosaukumu un DOI numuru norādiet kā vienkāršu tekstu, nevis otrādi — saiti DOI numuram un raksta nosaukumu kā vienkāršu tekstu.</p><div class="why"><p><a href="https://apastyle.apa.org/style-grammar-guidelines/paper-format/accessibility/urls#:~:text=descriptive%20links">APA stila rokasgrāmata</a> iesaka tīmekļa vietnēs izmantot aprakstošas saites, jo lietotāji pārskata lapas, vadoties pēc saitēm, un ar meklēšanu lapā meklē saites pēc nosaukuma. Lietotāji daudz biežāk pamanīs interesējošus rakstus, ja saite ir raksta nosaukums.</p><p>Tad arī ekrānlasītāji katru saiti var aprakstīt jēgpilni, nevis nolasīt bezjēdzīgu skaitļu virkni.</p></div>`,
  LINK_EMPTY: `<p>${why.fix}Pievienojiet tekstu, kas apraksta tās galamērķi, vai dzēsiet to, ja tā ir tikai drukas kļūda vai atstarpe ar saiti.</p><div class="why"><p>Padoms: ekrānlasītāji nevar aprakstīt saites, kas satur tikai atstarpes vai simbolus. Tās vai nu apklust (“Saite, [...neveikla pauze, kur vajadzētu būt saites nosaukumam...]”), vai nolasa URL: “Saite, H-T-T-P-S slīpsvītra slīpsvītra example punkts com.”</p><p>Ņemiet vērā, ka dažos satura redaktoros atstarpi ar saiti var būt grūti izdzēst; dažreiz ir jādzēš “pāri atstarpei”, izdzēšot un no jauna ierakstot vārdus abpus atstarpei ar saiti.</p></div>`,
  LINK_EMPTY_LABELLEDBY: `<p>Šai saitei ir <code>aria-labelledby</code> atribūts, kas neatbilst neviena lapas elementa <code>ID</code>.</p><p>${why.fix}Norādiet derīgu <code>ID</code> vai noņemiet šo atribūtu un aprakstiet saiti citā veidā.</p>`,
  LINK_EMPTY_NO_LABEL: `<p>${why.fix}Pievienojiet tekstu, kas apraksta tās galamērķi, vai dzēsiet to, ja tā ir tikai drukas kļūda, piemēram, atstarpe ar saiti.</p><div class="why"><p>Padoms: ekrānlasītāji nevar aprakstīt tukšas saites. Tās vai nu apklust (“Saite, [...neveikla pauze, kur vajadzētu būt saites nosaukumam...]”), vai nolasa URL: “Saite, H-T-T-P-S slīpsvītra slīpsvītra example punkts com.”</p><p>Ņemiet vērā, ka dažos satura redaktoros atstarpi ar saiti var būt grūti izdzēst; dažreiz ir jādzēš “pāri atstarpei”, izdzēšot un no jauna ierakstot vārdus abpus atstarpei ar saiti.</p></div>`,
  LINK_FILE_EXT: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>Šī saite norāda uz PDF vai lejupielādējamu failu (piemēram, MP3, ZIP, Word dokumentu) bez brīdinājuma.</p><p>${why.fix}Izmantojiet tekstu vai ikonu, lai <a href="https://itmaybejj.github.io/linkpurpose/">norādītu faila tipu</a> saites tekstā.</p><p class="why">Lieliem failiem ieteicams norādīt arī faila lielumu. Piemēram: “Vadības ziņojums (PDF, 3 MB)”</p>`,
  LINK_IDENTICAL_NAME: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Pārrakstiet saites, kas ved uz dažādām vietām, izmantojot katra galamērķa unikālo nosaukumu.</p>${why.links}`,
  LINK_IMAGE_ALT: `<p><strong>Alternatīvais teksts:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_IMAGE_ALT_AND_TEXT: `<p><strong>Alternatīvais teksts:</strong> <i>%(ALT_TEXT)</i></p><p><strong>Saites teksts, ieskaitot alternatīvo tekstu:</strong> <i>%(TEXT)</i></p><p>${why.fix}Mainiet vai noņemiet alternatīvo tekstu, ja tas pievieno nebūtisku vai lieku informāciju.</p>${why.imageLinks}`,
  LINK_IMAGE_LONG_ALT: `<p>Alternatīvā teksta garums (rakstzīmēs): %(altLength). <i class="ed11y-small">%(ALT_TEXT)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p><div class="why"><p>Ekrānlasītāju lietotāji bieži klausās lapas saišu sarakstu ārpus konteksta. Tā kā attēla ar saiti alternatīvais teksts kļūst par saites nosaukumu šajā sarakstā, tam vajadzētu <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">aprakstīt saites galamērķi</a>, nevis attēla saturu.</p></div>`,
  LINK_IMAGE_NO_ALT_TEXT: `<p>Ja attēls ir ievietots saitē, attēla alternatīvais teksts <a href="https://webaim.org/techniques/hypertext/link_text#alt_link">nodrošina saites nosaukumu ekrānlasītājiem</a>.</p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_IMAGE_TEXT: "Attēls ir atzīmēts kā dekoratīvs, lai gan saite izmanto apkārtējo tekstu kā aprakstošu etiķeti.",
  LINK_MAYBE_BUTTON: `<p><strong>Saite:</strong> <i>%(TEXT)</i></p><p>Šai saitei ir nederīga mērķadrese, un tās nosaukums liecina, ka tā, iespējams, darbojas kā poga vai pārslēgs, nevis kā saite.</p><p>${why.fix}Izmantojiet <a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/">&lt;button&gt;</a> elementu vai izlabojiet saites mērķadresi.</p><div class="why"><p>Padoms: palīgtehnoloģijas atšķirīgi apstrādā pogas un saites. Ja izmanto pareizo HTML elementu, lietotāji zina, kurus tastatūras taustiņus lietot un kāda darbība notiks.</p></div>`,
  LINK_NEW_TAB: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Iestatiet šo saiti tā, lai tā atvērtos tajā pašā cilnē, vai iepriekš <a href="https://itmaybejj.github.io/linkpurpose/">brīdiniet lietotājus</a>.</p><div class="why"><p>Lasītāji vienmēr var <em>izvēlēties</em> atvērt saiti jaunā cilnē. Ja saite piespiedu kārtā atveras jaunā cilnē, tas bieži mulsina vai kaitina, īpaši palīgtehnoloģiju lietotājus, kuri nesaprot, kāpēc pārlūkprogrammas poga “Atpakaļ” vairs nedarbojas.</p><p>Piezīme: izņēmums ir veidlapas. Ja lietotājs aizpilda veidlapu un saite atveras tajā pašā logā, viņš var zaudēt jau ievadīto, tāpēc saites veidlapās parasti atveras jaunā cilnē.</p></div>`,
  LINK_PLACEHOLDER_ALT: `<p><strong>Alternatīvais teksts:</strong> <i>%(alt)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_STOPWORD: `<p>Saites teksts: <i>%(ERROR)</i></p><p>${why.fix}Izmantojiet saites tekstu, kas apraksta tās galamērķi.</p>${why.links}`,
  LINK_STOPWORD_ARIA: `<p>Tika norādīts cits nosaukums, izmantojot ARIA:</p><p><strong>Redzamais teksts:</strong> <i>%(VISIBLE)</i></p><p><strong>Slēptais teksts:</strong> <i>%(HIDDEN)</i></p><p>${why.fix}Rakstiet jēgpilnas saites visiem, nevis tikai ekrānlasītāju lietotājiem, un pārliecinieties, ka katra elementa <a href="https://www.w3.org/WAI/WCAG22/Understanding/label-in-name.html">vizuālā etiķete atbilst tā nosaukumam</a>, lai balss vadības lietotāji varētu pateikt pārlūkprogrammai, uz kuras saites noklikšķināt.</p>${why.links}`,
  LINK_SUS_ALT: `<p>Ja vien “<i>%(alt)</i>” neapraksta saites galamērķi, šis alternatīvais teksts, visticamāk, apraksta attēlu.</p><p><strong>Alternatīvais teksts:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Attēliem ar saiti kā alternatīvo tekstu izmantojiet saites galamērķa nosaukumu.</p>${why.imageLinks}`,
  LINK_SYMBOLS: `<p>Atrasts simbols: <i>%(ERROR)</i></p><p>${why.fix}Neizmantojiet saišu tekstā simbolus kā aicinājumu uz darbību, ja vien tie nav paslēpti no palīgtehnoloģijām. Ekrānlasītāji var nolasīt simbolus skaļi, un tas var mulsināt.</p>`,
  LINK_UNPRONOUNCEABLE: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Pievienojiet tekstu vai title atribūtu, kas apraksta tās galamērķi, vai dzēsiet to, ja tā ir tikai drukas kļūda vai atstarpe ar saiti.</p><div class="why"><p>Padoms: ekrānlasītāji nevar aprakstīt saites, kas satur tikai atstarpes vai simbolus. Tās vai nu apklust (“Saite, [...neveikla pauze, kur vajadzētu būt saites nosaukumam...]”), vai nolasa simbola nosaukumu.</p></div>`,
  LINK_URL: `<p><strong>Saites teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Nomainiet saites tekstu ar tās galamērķa vai mērķa nosaukumu.</p><div class="why"><p>Padoms: lasītāji pārskata lapu, meklējot saites pēc nosaukuma. Īpaši tas attiecas uz ekrānlasītāju lietotājiem, kuri pārvietojas un meklē, izmantojot lapas saišu sarakstu.</p><p>URL saites tekstā ir grūti ātri pārskatīt un atrast ar meklēšanu lapā, tāpēc cilvēki tās retāk pamanīs un retāk uz tām noklikšķinās.</p></div>`,
  META_LANG: `<p>${why.fix}Pievienojiet <a href="https://www.w3.org/International/questions/qa-html-language-declarations">valodas atribūtu lapas HTML tagam</a>.</p><div class="why"><p>Padoms: ekrānlasītāji izrunā vārdus atbilstoši valodas tagiem. Ja tekstu izrunā ar nepareizas valodas pakotni, runa kļūst nesaprotama. Ja valoda nav norādīta, ekrānlasītājs vai nu izmantos pārlūkprogrammas noklusējuma valodu, vai mēģinās to uzminēt, un rezultāts būs neparedzams.</p></div>`,
  META_LANG_VALID: `<p><strong>Elements:</strong> <code>&lt;%(ELEMENT) lang="%(CODE)"&gt;</code></p><p>${why.fix}Aizstājiet lang atribūtu ar derīgu valodas kodu.</p><div class="why"><p>Padoms: lapām un elementiem ir <a href="https://www.w3.org/International/questions/qa-html-language-declarations">valodas atribūti</a>, lai ekrānlasītāji un tulkošanas rīki pareizi nolasītu tekstu.</p></div>`,
  META_MAX: `<p>Šis meta tags ierobežo, cik daudz lietotāji var palielināt tekstu.</p><p>${why.fix}Noņemiet vai mainiet šo ierobežojumu, lai tālummaiņa nebūtu ierobežota.</p>`,
  META_REFRESH: `<p>Lapas nedrīkst automātiski atsvaidzināt ar meta tagu. Tas pārtrauc lietotāju bez brīdinājuma un bez iespējas atsvaidzināšanu novērst, liek pazaudēt vietu, kur viņš lasīja, un var atiestatīt veidlapā jau ievadīto.</p><p>${why.fix}Lai atsvaidzinātu saturu tajā pašā lapā, izmantojiet AJAX un atsvaidziniet atsevišķas sadaļas bez lapas pārlādes vai arī pārlādējiet lapu ar JavaScript, lai lietotāju varētu iepriekš brīdināt un ļaut atsvaidzināšanu atlikt.</p>`,
  META_SCALABLE: `<p>Šis meta tags neļauj lietotājiem palielināt tekstu.</p><p>${why.fix}Noņemiet vai mainiet šo tagu, lai atļautu tālummaiņu bez ierobežojumiem.</p>`,
  META_TITLE: `<p>${why.fix}Pievienojiet lapas <code>head</code> elementā tagu <code>&lt;title&gt;</code>.</p><div class="why"><p>Padoms: daudz kas pārlūkošanā ir atkarīgs no <a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/title">īsa un unikāla title taga</a>:</p><ul><li>Meklētājprogrammas to izmanto kā rezultātu virsrakstu.</li><li>Pārlūkprogrammas to izmanto kā cilnes nosaukumu.</li><li>Ekrānlasītāji to nolasa, pārslēdzot cilnes.</li></ul><p>Bez lapas nosaukuma cilvēki redz/dzird neapstrādātu URL.</p></div>`,
  MISSING_ALT: `<p>Kad ekrānlasītāji saskaras ar attēlu bez alt atribūta, tie mēģina izrunāt attēla faila URL, bieži burtu pa burtam.</p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p>${why.images}`,
  MISSING_ALT_LINK: `<p>Kad ekrānlasītāji saskaras ar attēlu bez alt atribūta, tie mēģina izrunāt attēla faila URL, bieži burtu pa burtam. Īpaši liela problēma tā ir attēliem ar saiti.</p><p>${why.fix}Pievienojiet alternatīvo tekstu, kas atbilst saites galamērķim.</p>${why.imageLinks} `,
  MISSING_ALT_LINK_HAS_TEXT: `<p>Šis attēls ir daļa no saites, kurā ir teksts. Ja redzamais teksts ir pietiekams, lai aprakstītu saiti, pievienojiet tukšu alternatīvo tekstu (alt=""), lai ekrānlasītāji šo attēlu ignorētu. Pretējā gadījumā pievienojiet alternatīvo tekstu, kas palīdz aprakstīt saites galamērķi vai mērķi.</p>${why.imageLinks}`,
  QA_BAD_LINK: `<p>Šķiet, ka saite norāda uz izstrādes vidi:<br>{L} <code>%(LINK)</code></p><p>${why.fix}Nomainiet to ar relatīvu ceļu (/mape) vai publisko URL.</p>`,
  QA_BLOCKQUOTE: `<p><strong>Aizdomīgi īss citāts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Ja tas ir virsraksts, nevis citāts, formatējiet to kā virsrakstu, lai tas parādītos lapas struktūrā.</p>${why.headings}`,
  QA_DOCUMENT: `<p><strong>Saite:</strong> <i>%(TEXT)</i></p><p>Dokumenti, uz kuriem ved saites, arī ir tīmekļa saturs, un tiem arī jābūt piekļūstamiem. Pārbaudiet, vai šajā dokumentā ir marķēti virsraksti un tabulu galvenes un vai attēliem ir alternatīvais teksts.</p><div class="why"><ul><li>Padariet savu <a href="https://support.google.com/docs/answer/6199477?hl=lv">Google Workspace dokumentu vai prezentāciju piekļūstamāku.</a></li><li>Padariet savus <a href="https://support.microsoft.com/lv-lv/office/create-accessible-office-documents-868ecfcd-4f00-4224-b881-a65537a7c155">Office dokumentus piekļūstamākus.</a></li></ul></div>`,
  QA_FAKE_HEADING: `<p><strong>Teksts treknrakstā:</strong> <i>%(TEXT)</i></p><p>${why.fix}Ja šis teksts ir treknrakstā, lai iezīmētu jaunu tēmu, formatējiet to kā virsrakstu, lai ekrānlasītāju lietotāji to varētu izmantot, pārvietojoties lapā.</p><div class="why"><p>Padoms: treknraksts un kursīvs teksts vizuāli izceļ, taču nepievieno to dokumenta satura rādītājam, ko izmanto palīgtehnoloģijas.</p></div>`,
  QA_FAKE_LIST: `<p>${why.fix}Ja šis <i>%(TEXT)</i> ir daļa no saraksta, aizstājiet to ar saraksta formatējumu.</p><div class="why"><p>Padoms: saraksta formatējums ir strukturāls gan vizuāli, gan navigācijas ziņā:</p><ol><li>Sarakstos atkāpe ir vienmērīga, kas atvieglo lasīšanu.</li><li>Saraksti ir mašīnlasāmi. Ekrānlasītāji palīdz lietotājiem orientēties, regulāri paziņojot, kurā saraksta vietā viņi atrodas (“3. vienums no 7”).</li></ol><p>&nbsp;&nbsp;&nbsp;3. Taču teikumam ar skaitli sākumā, kā šim, otrā rindiņa netiek izlīdzināta ar atkāpi, un ekrānlasītāju lietotājiem tas netiek ieskaitīts vienumu skaitā.</p></div>`,
  QA_IN_PAGE_LINK: `<p><strong>URL:</strong> <i>#%(ID)</i></p><p><strong>Saite:</strong> <code>%(TEXT)</code></p><p>Saites mērķis neatbilst nevienam elementam šajā lapā.</p><div class="why"><p>Piezīme izstrādātājiem: ja šī nav parasta saite un tās mērķis ir JavaScript notikuma vietturis, pirms pievienojat to šī rīka ignorēšanas sarakstam, pārbaudiet, vai tā darbojas, aktivizējot to ar tastatūru.</p></div>`,
  QA_JUSTIFY: `<p>Abpusēji izlīdzinātā tekstā tiek ievietotas papildu atstarpes, lai rindkopas būtu izlīdzinātas gan gar kreiso, gan labo malu. Nevienmērīgās atstarpes katrā rindiņā daudziem cilvēkiem apgrūtina lasīšanu.</p><p>${why.fix}Izmantojiet pa kreisi izlīdzinātu tekstu.</p>`,
  QA_NESTED_COMPONENTS: "Neligzdojiet interaktīvus izkārtojuma komponentus, piemēram, akordeonus citos akordeonos vai cilnes akordeonos un otrādi. Tas var sarežģīt pārvietošanos, palielināt kognitīvo slodzi, un cilvēki var nepamanīt daļu satura.",
  QA_PDF: `<p><strong>Saite:</strong> <i>%(TEXT)</i></p><p>${why.fix}Veiciet vienu no šīm darbībām:</p><ul><li>Tā vietā izveidojiet saiti uz tīmekļa lapu,</li><li><em>Papildus</em> izveidojiet saiti uz tīmekļa lapu vai rediģējamu dokumentu, lai šis PDF būtu tikai “drukājamā” versija, vai</li><li>Vismaz pārliecinieties, ka šis PDF ir lasāms ar ekrānlasītājiem, <a href='https://webaim.org/techniques/acrobat/' target='_blank'>manuāli pārbaudot, vai tas ir marķēts</a> ar virsrakstiem, kolonnu lasīšanas secību, tabulu galvenēm un alternatīvo tekstu.</li></ul><div class="why"><p>Padoms: mobilo ierīču un palīgtehnoloģiju lietotāji gandrīz vienmēr dod priekšroku tīmekļa lapām, nevis PDF failiem. PDF saturs nepielāgojas mobilo ierīču ekrāniem, un tajos bieži trūkst tagu, kas nepieciešami, lai to tekstā varētu pārvietoties ar ekrānlasītāju.</p></div>`,
  QA_SMALL_TEXT: `<p><strong>Teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Neizmantojiet tekstu, kas mazāks par 80% no noklusējuma fonta lieluma. Mazs teksts ir grūti lasāms, īpaši cilvēkiem ar vāju redzi.</p>`,
  QA_STRONG_ITALICS: `<p><strong>Teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Treknrakstu un kursīvu izmantojiet tikai svarīgākajiem vārdiem un frāzēm.</p><div class="why"><p>Piezīme: ja tas ir citāts, to var nodalīt ar citāta bloka (blockquote) formatējumu.</p></div>`,
  QA_SUBSCRIPT: `<p><strong>Teksts:</strong> <i>%(TEXT)</i></p><p>Apakšraksta un augšraksta formatējums padara tekstu pārāk mazu, lai daudzi cilvēki to varētu viegli izlasīt. To drīkst izmantot tikai atsevišķiem vārdiem vai frāzēm, piemēram, mērvienībām (m<sup>2</sup>), ķīmiskajām formulām (H<sub>2</sub>O) un atsaucēm uz zemsvītras piezīmēm.</p>`,
  QA_UNDERLINE: `<p>Tīmeklī pasvītro saites, nevis uzsvērtu tekstu. Lietotāji domās, ka uz šī teksta var noklikšķināt: <i><u>%(TEXT)</u></i></p><p>${why.fix}Izmantojiet <strong>treknrakstu</strong> vai <em>kursīvu</em> uzsvaram un virsrakstus struktūrai.</p><div class="why"><p>Piezīme: ekrānlasītāji nepaziņo par tikai vizuālu formatējumu, piemēram, pasvītrojumiem. Lapas struktūrai tekstu pievieno tikai virsraksti.</p></div>`,
  QA_UPPERCASE: `<p><strong>Teksts:</strong> <i>%(TEXT)</i></p><p>${why.fix}Ar lielajiem burtiem izceliet tikai dažus vārdus. LIELI TEKSTA BLOKI AR LIELAJIEM BURTIEM IR GRŪTĀK LASĀMI, UN DAUDZI LASĪTĀJI TOS UZTVER KĀ KLIEGŠANU.</p><div class="why"><p>Piezīme: ekrānlasītāji nepaziņo par tikai vizuālu formatējumu, piemēram, lielajiem burtiem. Tā vietā izmantojiet virsraksta stilu, ja šis uzsvērtais teksts ievada tēmas maiņu vai kritiski svarīgu saturu.</p></div>`,
  SUS_ALT: `<p>Šī attēla alternatīvajā tekstā ir vārds “<i>%(alt)</i>”. Nolasot alternatīvo tekstu, ekrānlasītāji paši paziņo, ka apraksta attēlu, tāpēc tādi vārdi kā “attēls” un “fotoattēls” parasti ir lieki.</p><p><strong>Alternatīvais teksts:</strong> <i>%(ALT_TEXT)</i></p><p>${why.fix}Kodolīgi aprakstiet, ko šis attēls nozīmē šajā kontekstā.</p><div class="why"><p>Padoms: šos vārdus ir vērts saglabāt, ja pašam formātam ir nozīme:<br>“Kaķa fotoattēls, ierāmēts un piekārts pie sienas.”</p></div>`,
  TABINDEX_ATTR: `<p>Tabindex vērtības, kas lielākas par 0, pārvieto fokusējamos elementus ārpus to vizuālās secības, tāpēc palīgtehnoloģiju lietotājiem tos ir grūti atrast un lietot.</p><p>${why.fix}Tā vietā mainiet elementu secību HTML kodā, lai fokusa secība sakristu ar lasīšanas secību.</p><div class="why"><p>Padoms: vārdu vizuālā secība lapā parasti sakrīt ar secību, kādā elementos pārvietojas ar tastatūras tabulēšanas taustiņu.</p><p>Ja elementam piešķir pozitīvu tabindex vērtību, tas tiek pārvietots uz tabulēšanas secības sākumu, <strong>bet ne vizuālās vai lasīšanas secības sākumu</strong>.</p></div>`,
  TABLES_EMPTY_HEADING: `<p>${why.fix}Pārliecinieties, ka katra galvenes šūna satur tekstu.</p><div class="why"><p>Padoms: ekrānlasītāji izmanto galvenes, lai lietotāji varētu orientēties tabulā. Kad kursors nonāk citā kolonnā vai rindā, ekrānlasītājs atkārto attiecīgo galveni.</p></div>`,
  TABLES_INVALID_HEADERS_REF: `<p>Šajā tabulā konkrētai datu šūnai mēģināts piesaistīt konkrētu galvenes šūnu, bet galvenes ID nav atrasts: <code>%(VALUE)</code>.</p><p>${why.fix}Pārliecinieties, ka katrs <code>headers</code> atribūts atbilst galvenes šūnas ID tajā pašā tabulā.</p><div class="why">Padoms: <a href="https://www.w3.org/WAI/WCAG22/Techniques/html/H43">manuālu ID atsauču izmantošana</a>, lai saistītu datu šūnas ar galvenes šūnām, ir sarežģīta un viegli sabojājama. Ja iespējams, sadaliet sarežģītus datus mazākās tabulās ar vienkāršām galvenes rindām un kolonnām.</div>`,
  TABLES_MISSING_HEADINGS: `<p>${why.fix}Rediģējiet tabulas rekvizītus un norādiet, vai galvenes ir pirmajā rindā, pirmajā kolonnā vai abās.</p><div class="why"><p>Padoms: ekrānlasītāji izmanto galvenes, lai lietotāji varētu orientēties tabulā. Kad kursors nonāk citā kolonnā vai rindā, ekrānlasītājs atkārto attiecīgo galveni.</p><p>Ja šai tabulai nav galveņu, jo tā tiek izmantota tikai vizuālam izkārtojumam, noņemiet tabulas formatējumu un tā vietā izmantojiet tikai vizuālu kolonnu formatējumu.</p></div>`,
  TABLES_SEMANTIC_HEADING: `<p>${why.fix}Noņemiet šim tekstam virsraksta (h2, h3) formatējumu. Tā vietā izmantojiet galvenes rindas un kolonnas. Ja nepieciešamas vairākas galvenes rindas, sadaliet šo tabulu vairākās tabulās.</p><div class="why"><p>Padoms: tabulas galvene attiecas tikai uz vienu virzienu — savu rindu vai kolonnu. Satura virsraksts attiecas uz visu tam sekojošo tekstu, pat citās, nesaistītās kolonnās:</p><table><tr><th>1</th><th>2</th><th>3</th><td rowspan="2"><strong>Tabulas galvene</strong> šūnā 2 attiecas uz šūnu B. <br><br> <strong>Satura virsraksts</strong> šūnā 2 attiecas uz šūnām 3, A, B un C, kā arī uz šo tekstu un šī rīka padoma kājeni.</td></tr><tr><td>A</td><td>B</td><td>C</td></tr></table></div>`
};
